from collections import Counter, defaultdict

def transform(grid):
    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    marker_positions = defaultdict(list)
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != background:
                marker_positions[value].append((r, c))

    # Join aligned markers with the line color, leaving the markers unchanged.
    for positions in marker_positions.values():
        by_row = defaultdict(list)
        by_col = defaultdict(list)
        for r, c in positions:
            by_row[r].append(c)
            by_col[c].append(r)
        for r, cols in by_row.items():
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
        for c, rows in by_col.items():
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
